import {
  BundledAssetIdSchema,
  type BundledAssetId,
  type BundledAssetSpec,
} from "@tileborne/runtime";
import { Schema } from "effect";

import { PLUGIN_ID } from "../constants.js";

const PLAYER_PNG_BASE64 =
  "";

const PROJECTILE_PNG_BASE64 =
  "";

const SHIELD_PNG_BASE64 =
  "";

const SCAN_PULSE_PNG_BASE64 =
  "";

const DECOY_PNG_BASE64 =
  "";

const TRAP_PNG_BASE64 =
  "";

const LOOT_CRATE_PNG_BASE64 =
  "";

const WEAPON_RIFLE_PNG_BASE64 =
  "";
const IMPACT_BURST_PNG_BASE64 =
  "";
const SHADOW_PNG_BASE64 =
  "";

const WHITE_PIXEL_PNG_BASE64 =
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==";

const dataUrl = (base64: string): string => `data:image/png;base64,${base64}`;

const bundledAssetId = (assetKey: string): BundledAssetId =>
  Schema.decodeUnknownSync(BundledAssetIdSchema)(`${PLUGIN_ID}:${assetKey}`);

export const PLAYER_TEXTURE_ASSET_ID = bundledAssetId("default-pet");
export const PROJECTILE_TEXTURE_ASSET_ID = bundledAssetId("projectile-bolt");
export const SHIELD_TEXTURE_ASSET_ID = bundledAssetId("shield-burst");
export const SCAN_PULSE_TEXTURE_ASSET_ID = bundledAssetId("scan-pulse");
export const DECOY_TEXTURE_ASSET_ID = bundledAssetId("decoy");
export const TRAP_TEXTURE_ASSET_ID = bundledAssetId("trap");
export const LOOT_CRATE_TEXTURE_ASSET_ID = bundledAssetId("loot-crate");
export const WEAPON_RIFLE_TEXTURE_ASSET_ID = bundledAssetId("weapon-rifle");
export const IMPACT_BURST_TEXTURE_ASSET_ID = bundledAssetId("impact-burst");
export const SHADOW_TEXTURE_ASSET_ID = bundledAssetId("shadow");
export const UI_PIXEL_TEXTURE_ASSET_ID = bundledAssetId("ui-pixel");

export const createBattleRoyaleBundledAssets = (): readonly BundledAssetSpec[] => [
  {
    assetId: PLAYER_TEXTURE_ASSET_ID,
    path: dataUrl(PLAYER_PNG_BASE64),
    mime: "image/png",
    width: 48,
    height: 48,
  },
  {
    assetId: PROJECTILE_TEXTURE_ASSET_ID,
    path: dataUrl(PROJECTILE_PNG_BASE64),
    mime: "image/png",
    width: 48,
    height: 48,
  },
  {
    assetId: SHIELD_TEXTURE_ASSET_ID,
    path: dataUrl(SHIELD_PNG_BASE64),
    mime: "image/png",
    width: 48,
    height: 48,
  },
  {
    assetId: SCAN_PULSE_TEXTURE_ASSET_ID,
    path: dataUrl(SCAN_PULSE_PNG_BASE64),
    mime: "image/png",
    width: 48,
    height: 48,
  },
  {
    assetId: DECOY_TEXTURE_ASSET_ID,
    path: dataUrl(DECOY_PNG_BASE64),
    mime: "image/png",
    width: 48,
    height: 48,
  },
  {
    assetId: TRAP_TEXTURE_ASSET_ID,
    path: dataUrl(TRAP_PNG_BASE64),
    mime: "image/png",
    width: 48,
    height: 48,
  },
  {
    assetId: LOOT_CRATE_TEXTURE_ASSET_ID,
    path: dataUrl(LOOT_CRATE_PNG_BASE64),
    mime: "image/png",
    width: 48,
    height: 48,
  },
  {
    assetId: WEAPON_RIFLE_TEXTURE_ASSET_ID,
    path: dataUrl(WEAPON_RIFLE_PNG_BASE64),
    mime: "image/png",
    width: 48,
    height: 48,
  },
  {
    assetId: IMPACT_BURST_TEXTURE_ASSET_ID,
    path: dataUrl(IMPACT_BURST_PNG_BASE64),
    mime: "image/png",
    width: 48,
    height: 48,
  },
  {
    assetId: SHADOW_TEXTURE_ASSET_ID,
    path: dataUrl(SHADOW_PNG_BASE64),
    mime: "image/png",
    width: 48,
    height: 48,
  },
  {
    assetId: UI_PIXEL_TEXTURE_ASSET_ID,
    path: dataUrl(WHITE_PIXEL_PNG_BASE64),
    mime: "image/png",
    width: 1,
    height: 1,
  },
];
